import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md","lastUpdated":1785861127000}'),r={name:"en/guide/faq.md"};function n(s,e,l,d,h,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-any-setup-required-after-installing" tabindex="-1">Is any setup required after installing? <a class="header-anchor" href="#is-any-setup-required-after-installing" aria-label="Permalink to &quot;Is any setup required after installing?&quot;">​</a></h2><p>No. The default configuration already enables cache cleaning, background suppression, garbage collection and empty-folder cleanup; after a reboot it runs in the background on schedule. CZeroX is for viewing status and adjusting settings — it is not required.</p><h2 id="do-i-need-to-reboot-after-changing-a-setting" tabindex="-1">Do I need to reboot after changing a setting? <a class="header-anchor" href="#do-i-need-to-reboot-after-changing-a-setting" aria-label="Permalink to &quot;Do I need to reboot after changing a setting?&quot;">​</a></h2><p>No. Saving is enough.</p><h2 id="which-root-solutions-are-supported" tabindex="-1">Which root solutions are supported? <a class="header-anchor" href="#which-root-solutions-are-supported" aria-label="Permalink to &quot;Which root solutions are supported?&quot;">​</a></h2><p>Magisk, KernelSU and APatch. The device must run Android 9 or newer on <code>arm64</code>.</p><h2 id="can-i-use-it-without-czerox" tabindex="-1">Can I use it without CZeroX? <a class="header-anchor" href="#can-i-use-it-without-czerox" aria-label="Permalink to &quot;Can I use it without CZeroX?&quot;">​</a></h2><p>Yes, the module runs independently. However, there is then no graphical interface and settings must be edited by hand in the config file, which is not recommended.</p><h2 id="could-cleaning-remove-data-i-care-about" tabindex="-1">Could cleaning remove data I care about? <a class="header-anchor" href="#could-cleaning-remove-data-i-care-about" aria-label="Permalink to &quot;Could cleaning remove data I care about?&quot;">​</a></h2><p>Cleaning targets only caches and leftover directories, with two layers of protection:</p><ul><li><strong>Temporal barrier</strong> — by default only files older than 3 days are processed, leaving recent data untouched. Raise the value for a more conservative setup.</li><li><strong>Recycle bin</strong> — cleaning does not delete outright; files are first moved to the recycle bin and kept for 7 days, fully recoverable during that window.</li></ul><h2 id="how-do-i-restore-a-file-removed-by-mistake" tabindex="-1">How do I restore a file removed by mistake? <a class="header-anchor" href="#how-do-i-restore-a-file-removed-by-mistake" aria-label="Permalink to &quot;How do I restore a file removed by mistake?&quot;">​</a></h2><p>Find the record in CZeroX&#39;s <strong>Recycle bin</strong> and restore it; the file is moved back to its original location as it was. Records past the retention period are purged automatically and can no longer be restored.</p><p>The retention period can be raised in the recycle-bin settings, at the cost of more storage used.</p><h2 id="my-device-isn-t-f2fs-—-can-i-still-use-it" tabindex="-1">My device isn&#39;t F2FS — can I still use it? <a class="header-anchor" href="#my-device-isn-t-f2fs-—-can-i-still-use-it" aria-label="Permalink to &quot;My device isn&#39;t F2FS — can I still use it?&quot;">​</a></h2><p>Yes. Everything except <strong>F2FS garbage collection</strong> is independent of the filesystem type. On a non-F2FS device, simply turn that feature off.</p><h2 id="garbage-collection-never-seems-to-run" tabindex="-1">Garbage collection never seems to run? <a class="header-anchor" href="#garbage-collection-never-seems-to-run" aria-label="Permalink to &quot;Garbage collection never seems to run?&quot;">​</a></h2><p>This is expected. Garbage collection does not run merely because it is scheduled; all of the following must hold:</p><ul><li>storage genuinely needs reclaiming (nothing to do when free space is ample);</li><li>enough time has passed since the last run;</li><li>the screen is off;</li><li>the battery has sufficient charge and a normal temperature.</li></ul><p>Consequently, never observing it run usually indicates the device is in good shape. To confirm, enable logging — the log records which condition caused the round to be skipped.</p><h2 id="how-does-fstrim-differ-from-garbage-collection" tabindex="-1">How does fstrim differ from garbage collection? <a class="header-anchor" href="#how-does-fstrim-differ-from-garbage-collection" aria-label="Permalink to &quot;How does fstrim differ from garbage collection?&quot;">​</a></h2><p><strong>Garbage collection</strong> consolidates fragmentation within the device&#39;s filesystem; <strong>fstrim</strong> informs the storage device which space has been freed, so its own reclamation has something to work with. The two are complementary, both enabled by default, and require no further configuration.</p><h2 id="how-does-fine-grained-suppression-differ-from-background-suppression" tabindex="-1">How does fine-grained suppression differ from background suppression? <a class="header-anchor" href="#how-does-fine-grained-suppression-differ-from-background-suppression" aria-label="Permalink to &quot;How does fine-grained suppression differ from background suppression?&quot;">​</a></h2><ul><li><strong>Background suppression</strong> — terminates background processes outright, freeing memory immediately at the cost of a full reload next launch.</li><li><strong>Fine-grained suppression</strong> — suspends the app without terminating it, stopping CPU usage while preserving its full runtime state for instant resumption.</li></ul><p>Use the former to reclaim resources thoroughly, the latter to preserve the app&#39;s live state. Both can be enabled at once. Fine-grained suppression requires Android 12 or newer.</p><h2 id="will-reinstalling-or-updating-lose-my-settings" tabindex="-1">Will reinstalling or updating lose my settings? <a class="header-anchor" href="#will-reinstalling-or-updating-lose-my-settings" aria-label="Permalink to &quot;Will reinstalling or updating lose my settings?&quot;">​</a></h2><p>No. Choose <strong>inherit</strong> when flashing: existing rules, whitelists and adjusted options are all retained, and options added by the new version are filled in automatically.</p><h2 id="does-uninstalling-leave-files-behind" tabindex="-1">Does uninstalling leave files behind? <a class="header-anchor" href="#does-uninstalling-leave-files-behind" aria-label="Permalink to &quot;Does uninstalling leave files behind?&quot;">​</a></h2><p>No. Remove the module in your root manager and reboot; the module directory is cleared along with its statistics and logs. The recycle bin resides in the <code>Recycle</code> folder on internal storage and can be deleted manually for a complete cleanup.</p><h2 id="where-can-i-view-the-logs" tabindex="-1">Where can I view the logs? <a class="header-anchor" href="#where-can-i-view-the-logs" aria-label="Permalink to &quot;Where can I view the logs?&quot;">​</a></h2><p>Enable logging in CZeroX and logs are stored in the module&#39;s <code>log</code> folder, keeping only the current day. Attaching a log when reporting an issue helps considerably.</p><h2 id="how-do-i-report-an-issue" tabindex="-1">How do I report an issue? <a class="header-anchor" href="#how-do-i-report-an-issue" aria-label="Permalink to &quot;How do I report an issue?&quot;">​</a></h2><p>Please open one on <a href="https://github.com/Xocio/CZero/issues" target="_blank" rel="noreferrer">GitHub Issues</a>, or join the <a href="https://t.me/+lwNKCHw_NktjODRh" target="_blank" rel="noreferrer">group chat</a>.</p><p>For detailed descriptions of each feature see <a href="/en/guide/features">Features</a>; for field-by-field configuration see <a href="/en/guide/configuration">Configuration</a>.</p>',35)])])}const f=a(r,[["render",n]]);export{g as __pageData,f as default};
